  e ∈ M.closure (X \ {e}) ↔ M.closure (X \ {e}) = M.closure X

theorem Matroid.IsBase.exchange_base_of_notMem_closure.{u_2} {α : Type u_2} {M : Matroid α} {e f : α}
  {B : Set α} (hB : M.IsBase B) (he : e ∈ B) (hf : f ∉ M.closure (B \ {e}))
  (hfE : f ∈ M.E := by aesop_mat) : M.IsBase (insert f (B \ {e}))

theorem Matroid.Indep.inter_isBasis_sInter.{u_2} {α : Type u_2} {M : Matroid α} {I : Set α}
  {Xs : Set (Set α)} (hI : M.Indep I) (hXs : Xs.Nonempty) (h : ∀ X ∈ Xs, M.IsBasis (X ∩ I) X) :
  M.IsBasis (⋂₀ Xs ∩ I) (⋂₀ Xs)
